(x, y, t) => {
  const wx1 = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy1 = Math.cos(y*0.02-t*0.25)*18 + Math.sin(x*0.016+t*0.35)*12 + Math.cos((x-y)*0.012-t*0.4)*8;
  const wx2 = Math.sin(wx1*0.03+wy1*0.02+t*0.7)*10;
  const wy2 = Math.cos(wx1*0.025-wy1*0.035-t*0.6)*10;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const cx=240, cy=120;
  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.3],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,-0.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,-0.3],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.5],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,-0.4],
    [80+Math.sin(t*0.45+3)*110,40+Math.cos(t*0.65+2)*60,0.11,2.1,0.35],
    [400+Math.cos(t*0.55+1)*70,220+Math.sin(t*0.75+4)*50,0.075,2.4,-0.25]
  ];
  let aS=0,iS=0,cr=0;
  for(let i=0;i<8;i++){
    const[sX,sY,f,sp,ph]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    const j=(i+1)%8;
    const[sX2,sY2,f2,sp2]=src[j];
    const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
    cr+=Math.sin(d*f+d2*f2-t*(sp+sp2)*0.5)*0.5;
  }
  const act=aS/8,inh=iS/8,crs=cr/8;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08+Math.cos(sy*0.06+t)*2+t*1.5)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2-t*0.8)*0.5)*0.3;
  const nl=Math.tanh(act*act-inh*inh)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+crs*0.4+nl)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const ripple=Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.2;
  const blend=reaction*0.55+cell*0.2+crs*0.15+ripple*0.1;
  const v=blend*0.5+0.5;
  const pal=[[10,15,60],[15,45,90],[20,85,115],[25,140,130],[80,170,120],[180,190,70],[220,170,55],[230,120,65],[200,75,70],[150,50,75],[90,30,80],[45,20,65],[10,15,60]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const w=Math.sin(t*0.15)*0.08;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+w*30)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f-w*20)*lum*edge)|0
  ];
}
